insert into public.questions (subject_id, source_ref, prompt, options, correct_index, explanation, difficulty, topic, question_type, status, sort_order, banca, concurso)
values
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-001', 'Um município publica edital para conceder licença de funcionamento e passa a exigir documento sem previsão legal. Qual princípio administrativo é diretamente tensionado por essa exigência?', '["Eficiência, pois todo documento adicional reduz a produtividade.","Legalidade, pois a Administração deve atuar conforme autorização normativa.","Continuidade, pois a licença deve ser concedida imediatamente.","Publicidade, pois o documento deveria ser sigiloso.","Especialidade, pois municípios não podem licenciar atividades."]'::jsonb, 1, 'Pelo princípio da legalidade administrativa, a exigência precisa ter fundamento jurídico; conveniência do agente não substitui autorização normativa.', 'easy', 'Princípios da Administração', 'multiple_choice', 'published', 5000, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-002', 'A Administração identifica que uma licença foi concedida em desacordo com requisito legal obrigatório. Em regra, qual providência corresponde à autotutela sobre esse ato ilegal?', '["Revogar o ato por motivo de conveniência, preservando sua validade.","Anular o ato, observados os limites legais e as garantias aplicáveis.","Convalidar sempre o ato, ainda que o vício seja insanável.","Transferir a decisão ao Poder Legislativo.","Manter o ato porque atos administrativos não podem ser revistos."]'::jsonb, 1, 'A autotutela permite anular atos ilegais. Revogação é retirada de ato válido por razões de conveniência e oportunidade.', 'medium', 'Autotutela administrativa', 'multiple_choice', 'published', 5001, 'FCC', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-administrativo'), 'LAW-AUTH-003', 'Durante fiscalização, um órgão aplica sanção a estabelecimento sem permitir defesa prévia nem recurso, embora a lei os preveja. Qual conclusão é mais adequada?', '["O poder de polícia afasta qualquer garantia processual.","A sanção é válida se o estabelecimento tiver sido fiscalizado.","O exercício do poder de polícia deve respeitar o devido processo e a defesa previstos em lei.","Somente o Judiciário pode aplicar sanções administrativas.","A publicidade do ato substitui a oportunidade de defesa."]'::jsonb, 2, 'O poder de polícia não elimina o devido processo legal, o contraditório e a ampla defesa quando exigidos para a imposição da sanção.', 'medium', 'Poder de polícia', 'multiple_choice', 'published', 5002, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-004', 'Um grupo pretende criar uma associação lícita para defender interesses culturais. Segundo a Constituição, a criação de associações depende de autorização estatal?', '["Sim, sempre depende de autorização do Poder Executivo.","Sim, desde que a associação tenha finalidade econômica.","Não; a criação é livre, vedada a interferência estatal em seu funcionamento, nos termos constitucionais.","Não, mas somente partidos podem se associar livremente.","Sim, depende de autorização judicial prévia."]'::jsonb, 2, 'A Constituição assegura a liberdade de associação para fins lícitos e veda interferência estatal no funcionamento, ressalvadas as regras constitucionais.', 'easy', 'Direitos fundamentais: associação', 'multiple_choice', 'published', 5003, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-005', 'Uma pessoa quer conhecer e corrigir dado pessoal próprio mantido em cadastro de entidade governamental. Qual instrumento constitucional é voltado especificamente a essa finalidade?', '["Mandado de injunção.","Habeas data.","Ação popular.","Habeas corpus.","Mandado de segurança coletivo."]'::jsonb, 1, 'O habeas data permite conhecer informações relativas à própria pessoa em registros públicos ou de caráter público e, conforme o caso, retificá-las.', 'medium', 'Remédios constitucionais', 'multiple_choice', 'published', 5004, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-006', 'Uma lei municipal disciplina o horário de funcionamento de estabelecimentos locais, sem contrariar norma federal ou estadual aplicável. A competência legislativa municipal pode fundamentar-se principalmente no interesse:', '["Nacional, com exclusividade da União.","Local, atribuído ao município pela Constituição.","Internacional, reservado ao Senado.","Militar, de competência estadual.","Tributário federal, reservado à Receita Federal."]'::jsonb, 1, 'A Constituição atribui aos municípios competência para legislar sobre assuntos de interesse local, respeitadas as demais normas constitucionais.', 'medium', 'Competências municipais', 'multiple_choice', 'published', 5005, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-007', 'Uma conduta socialmente reprovável não está descrita como crime em lei anterior. À luz do princípio da legalidade, é correto afirmar que:', '["Pode haver condenação se a analogia for desfavorável ao acusado.","Não há crime nem pena sem lei anterior que os estabeleça.","O costume pode criar crime, desde que reiterado.","A decisão administrativa pode substituir a lei penal.","A lei posterior mais gravosa retroage para punir o fato."]'::jsonb, 1, 'A legalidade penal exige lei anterior para definir crime e cominar pena, vedada a analogia em prejuízo do acusado.', 'easy', 'Princípio da legalidade penal', 'multiple_choice', 'published', 5006, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-008', 'Durante a execução de um delito, o agente, por decisão própria, interrompe a conduta antes da consumação, embora pudesse prosseguir. Em regra, configura-se:', '["Crime impossível, com punição pelo resultado pretendido.","Desistência voluntária, respondendo o agente pelos atos já praticados.","Arrependimento posterior, com extinção automática da punibilidade.","Tentativa punível pelo resultado consumado.","Erro de tipo inevitável."]'::jsonb, 1, 'Na desistência voluntária, o agente interrompe voluntariamente a execução e responde pelos atos já praticados, se constituírem infração.', 'medium', 'Tentativa e desistência voluntária', 'multiple_choice', 'published', 5007, 'FGV', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-009', 'Para afastar agressão injusta, atual e iminente contra terceiro, uma pessoa usa moderadamente meio necessário. A situação pode caracterizar:', '["Estado de necessidade, ainda que não exista perigo atual.","Legítima defesa de terceiro.","Exercício arbitrário das próprias razões.","Estrito cumprimento de dever legal, necessariamente.","Erro de proibição."]'::jsonb, 1, 'A legítima defesa também pode proteger direito de terceiro, diante de agressão injusta atual ou iminente, com uso moderado dos meios necessários.', 'medium', 'Legítima defesa', 'multiple_choice', 'published', 5008, 'FCC', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-010', 'Na execução de um contrato, uma parte fornece informação relevante e coopera para evitar prejuízo injustificado à outra. Essa conduta se relaciona principalmente ao dever de:', '["Boa-fé objetiva e lealdade contratual.","Presunção absoluta de inadimplemento.","Renúncia prévia a direitos da personalidade.","Irrevogabilidade de qualquer contrato.","Responsabilidade penal objetiva."]'::jsonb, 0, 'A boa-fé objetiva impõe padrões de lealdade, cooperação e confiança durante a formação e execução dos contratos.', 'easy', 'Boa-fé objetiva', 'multiple_choice', 'published', 5009, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-011', 'Em regra, a responsabilidade civil subjetiva exige a presença de:', '["Dano e enriquecimento, apenas.","Conduta, dano, nexo causal e culpa ou dolo, ressalvadas hipóteses legais de responsabilidade objetiva.","Contrato escrito e dano moral.","Dolo específico e condenação criminal anterior.","Apenas conduta e dano, em qualquer hipótese."]'::jsonb, 1, 'Na responsabilidade subjetiva, analisam-se conduta, dano, nexo causal e elemento de culpa ou dolo. A lei prevê hipóteses objetivas.', 'medium', 'Responsabilidade civil', 'multiple_choice', 'published', 5010, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-012', 'Uma pessoa tem sua imagem usada comercialmente sem autorização. Além de eventual reparação, pode buscar tutela para:', '["Impedir ou fazer cessar a utilização ilícita, conforme o caso.","Transferir automaticamente sua personalidade a terceiro.","Anular todos os contratos celebrados pelo responsável.","Obter condenação criminal sem processo.","Impedir qualquer crítica pública, ainda que legítima."]'::jsonb, 0, 'Os direitos da personalidade admitem tutela preventiva ou inibitória contra ameaça ou lesão, além de eventual reparação, ponderadas as circunstâncias.', 'medium', 'Direitos da personalidade', 'multiple_choice', 'published', 5011, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-013', 'Em regra, no processo civil, cabe ao autor provar o fato constitutivo de seu direito e ao réu provar fato impeditivo, modificativo ou extintivo. Essa regra trata:', '["Da competência absoluta.","Do ônus da prova.","Da coisa julgada.","Da capacidade postulatória.","Do princípio da publicidade."]'::jsonb, 1, 'A distribuição ordinária do ônus da prova atribui ao autor os fatos constitutivos e ao réu os fatos impeditivos, modificativos ou extintivos.', 'medium', 'Ônus da prova', 'multiple_choice', 'published', 5012, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-014', 'Para conceder tutela de urgência, o CPC exige, em regra:', '["Somente pedido expresso, sem análise dos fatos.","Probabilidade do direito e perigo de dano ou risco ao resultado útil do processo.","Trânsito em julgado e ausência de recurso.","Confissão da parte contrária.","Prova exclusivamente testemunhal."]'::jsonb, 1, 'A tutela de urgência pressupõe elementos que evidenciem a probabilidade do direito e o perigo de dano ou risco ao resultado útil do processo.', 'medium', 'Tutela provisória de urgência', 'multiple_choice', 'published', 5013, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-015', 'A revelia do réu, no procedimento comum, pode produzir presunção de veracidade das alegações de fato do autor, mas essa consequência:', '["É absoluta e obriga o juiz a acolher todo pedido.","Não ocorre nas hipóteses legais de exceção e não dispensa o exame jurídico do pedido.","Transforma automaticamente o pedido em título executivo extrajudicial.","Impede o autor de produzir provas.","Extingue o processo sem resolução do mérito."]'::jsonb, 1, 'Os efeitos materiais da revelia não são absolutos: há exceções legais, e o juiz ainda deve verificar as consequências jurídicas dos fatos e os requisitos do pedido.', 'hard', 'Revelia', 'multiple_choice', 'published', 5014, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-016', 'Durante interrogatório, a pessoa investigada opta por permanecer em silêncio. Essa escolha:', '["Pode ser valorada como confissão.","É garantia constitucional e não deve ser interpretada em prejuízo da defesa.","Extingue automaticamente a investigação.","Impede a presença de advogado.","Só é válida após autorização judicial."]'::jsonb, 1, 'O direito ao silêncio integra as garantias de não autoincriminação e não pode ser tratado como confissão ou fundamento autônomo de culpa.', 'easy', 'Direito ao silêncio', 'multiple_choice', 'published', 5015, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-017', 'Sobre a prisão em flagrante, é correto afirmar que:', '["Somente juiz pode efetuar a captura material do suspeito.","Qualquer pessoa pode prender quem esteja em flagrante, e autoridades policiais e seus agentes devem fazê-lo.","A prisão dispensa comunicação às autoridades competentes.","Ela depende sempre de mandado judicial.","A autoridade policial pode manter a prisão sem controle judicial."]'::jsonb, 1, 'O CPP prevê que qualquer pessoa pode prender quem esteja em flagrante delito, enquanto autoridades policiais e seus agentes têm o dever legal de fazê-lo.', 'medium', 'Prisão em flagrante', 'multiple_choice', 'published', 5016, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='processo-penal'), 'LAW-AUTH-018', 'O inquérito policial é, em regra, procedimento informativo e escrito. Sua conclusão:', '["É requisito indispensável em todo caso para o oferecimento da ação penal.","Não impede a ação penal quando já houver elementos informativos suficientes por outras fontes lícitas.","Substitui a instrução judicial e a defesa.","Produz condenação automática.","É julgada pelo delegado com força de coisa julgada."]'::jsonb, 1, 'O inquérito auxilia a formação da opinião do titular da ação penal, mas não é condição indispensável quando já existem elementos suficientes obtidos licitamente.', 'medium', 'Inquérito policial', 'multiple_choice', 'published', 5017, 'VUNESP', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-do-trabalho'), 'LAW-AUTH-019', 'Uma pessoa presta serviços pessoalmente, de modo não eventual, remunerado e sob subordinação. Esses elementos, presentes em conjunto e conforme a realidade, indicam:', '["Relação de emprego.","Trabalho voluntário necessariamente.","Contrato de sociedade.","Empreitada sem pessoalidade.","Trabalho autônomo em qualquer situação."]'::jsonb, 0, 'Pessoalidade, não eventualidade, onerosidade e subordinação são elementos clássicos da relação de emprego, examinados conforme os fatos.', 'easy', 'Relação de emprego', 'multiple_choice', 'published', 5018, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-do-trabalho'), 'LAW-AUTH-020', 'Como regra geral constitucional, a duração normal do trabalho não deve superar:', '["6 horas diárias e 30 semanais em toda atividade.","8 horas diárias e 44 semanais, admitidas compensações na forma legal.","10 horas diárias e 60 semanais sem limite.","12 horas diárias, sem acordo ou previsão legal.","44 horas diárias e 8 semanais."]'::jsonb, 1, 'A Constituição estabelece duração normal não superior a oito horas diárias e quarenta e quatro semanais, admitida compensação nos termos aplicáveis.', 'medium', 'Jornada de trabalho', 'multiple_choice', 'published', 5019, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-do-trabalho'), 'LAW-AUTH-021', 'Após completar o período aquisitivo de férias, o empregado deve usufruir o descanso:', '["Somente se o empregador quiser, sem prazo.","No período concessivo previsto em lei, observadas as regras trabalhistas.","Imediatamente no mesmo dia, sem possibilidade de programação.","Apenas após cinco anos de serviço.","Somente mediante autorização sindical individual."]'::jsonb, 1, 'A CLT prevê período aquisitivo e período concessivo: completado o primeiro, o empregador deve conceder as férias dentro do prazo legal subsequente.', 'medium', 'Férias', 'multiple_choice', 'published', 5020, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-tributario'), 'LAW-AUTH-022', 'Como regra geral, a instituição ou majoração de tributo depende de:', '["Decreto autônomo, em qualquer caso.","Lei, ressalvadas as exceções constitucionais expressas.","Portaria de qualquer órgão administrativo.","Decisão judicial individual.","Contrato entre Fisco e contribuinte."]'::jsonb, 1, 'A legalidade tributária exige lei para instituir ou majorar tributos, sem prejuízo das exceções constitucionais específicas.', 'medium', 'Legalidade tributária', 'multiple_choice', 'published', 5021, 'CEBRASPE', 'Área fiscal'),
((select id from public.subjects where slug='direito-tributario'), 'LAW-AUTH-023', 'No CTN, a obrigação principal tem por objeto:', '["Apenas a entrega de declarações, sem conteúdo pecuniário.","O pagamento de tributo ou penalidade pecuniária.","Somente a emissão de notas fiscais.","A prestação de serviço público pelo contribuinte.","A inscrição em cadastro municipal, exclusivamente."]'::jsonb, 1, 'A obrigação principal surge com a ocorrência do fato gerador e tem por objeto o pagamento de tributo ou penalidade pecuniária.', 'medium', 'Obrigação tributária', 'multiple_choice', 'published', 5022, 'VUNESP', 'Área fiscal'),
((select id from public.subjects where slug='direito-tributario'), 'LAW-AUTH-024', 'A competência tributária é atribuída pela Constituição aos entes federativos. Em regra, essa competência:', '["Pode ser livremente transferida por contrato privado.","Não se confunde com a capacidade de arrecadar ou fiscalizar tributos.","É criada por portaria do órgão arrecadador.","Pertence exclusivamente à União.","Desaparece quando o ente deixa de exercer a fiscalização."]'::jsonb, 1, 'Competência tributária é o poder constitucional de instituir tributos; capacidade tributária ativa para arrecadar ou fiscalizar pode receber tratamento distinto.', 'hard', 'Competência tributária', 'multiple_choice', 'published', 5023, 'CEBRASPE', 'Área fiscal'),
((select id from public.subjects where slug='direito-do-consumidor'), 'LAW-AUTH-025', 'Uma consumidora compra um produto pela internet e, dentro do prazo legal, decide desistir da compra. O CDC prevê, nas contratações fora do estabelecimento comercial, direito de arrependimento em:', '["24 horas, sem restituição de valores.","7 dias, contados conforme a regra legal, com devolução dos valores pagos.","30 dias, apenas se houver defeito.","90 dias, somente para produtos duráveis.","Nenhum prazo de desistência."]'::jsonb, 1, 'O art. 49 do CDC prevê prazo de sete dias para arrependimento em contratação fora do estabelecimento comercial, com devolução dos valores pagos.', 'easy', 'Direito de arrependimento', 'multiple_choice', 'published', 5024, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-do-consumidor'), 'LAW-AUTH-026', 'Em ação por fato do produto, a responsabilidade do fornecedor é, em regra:', '["Subjetiva em todas as hipóteses, exigindo prova de dolo.","Objetiva, observadas as excludentes previstas em lei.","Inexistente se o produto foi adquirido pela internet.","Exclusiva do comerciante em qualquer situação.","Dependente de condenação criminal."]'::jsonb, 1, 'O CDC estabelece responsabilidade objetiva pelo fato do produto, sem prejuízo das excludentes legais, como prova de inexistência do defeito ou culpa exclusiva do consumidor ou de terceiro.', 'medium', 'Responsabilidade pelo produto', 'multiple_choice', 'published', 5025, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-do-consumidor'), 'LAW-AUTH-027', 'A inversão do ônus da prova em favor do consumidor pode ser determinada pelo juiz quando:', '["For automática em toda demanda, sem análise.","Houver verossimilhança da alegação ou hipossuficiência, conforme apreciação judicial.","O fornecedor concordar por escrito.","A ação envolver apenas danos materiais.","O consumidor renunciar ao direito de informação."]'::jsonb, 1, 'O art. 6º, VIII, do CDC autoriza a inversão quando, a critério do juiz, a alegação for verossímil ou o consumidor for hipossuficiente.', 'medium', 'Inversão do ônus da prova', 'multiple_choice', 'published', 5026, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-028', 'A Constituição reconhece o meio ambiente ecologicamente equilibrado como bem de uso comum e impõe o dever de defendê-lo:', '["Somente aos órgãos federais.","Ao Poder Público e à coletividade.","Apenas aos proprietários rurais.","Exclusivamente às empresas licenciadas.","Somente às gerações futuras."]'::jsonb, 1, 'O art. 225 da Constituição atribui ao Poder Público e à coletividade o dever de defender e preservar o meio ambiente para as presentes e futuras gerações.', 'easy', 'Dever de proteção ambiental', 'multiple_choice', 'published', 5027, 'VUNESP', 'Área fiscal'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-029', 'A responsabilidade civil por dano ambiental é, em regra, caracterizada como:', '["Subjetiva, sempre condicionada à prova de dolo.","Objetiva, sem afastar a necessidade de dano e nexo causal.","Administrativa apenas, sem reparação civil.","Inexistente quando a atividade possui licença.","Dependente de condenação penal transitada em julgado."]'::jsonb, 1, 'A responsabilidade civil ambiental é objetiva; ainda assim, a identificação do dano e do nexo causal continua relevante para a reparação.', 'medium', 'Responsabilidade ambiental', 'multiple_choice', 'published', 5028, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-ambiental'), 'LAW-AUTH-030', 'Quando existe incerteza científica relevante sobre risco de dano ambiental grave, a adoção de medidas preventivas relaciona-se especialmente ao princípio da:', '["Precaução.","Especialidade.","Anterioridade tributária.","Insignificância penal.","Autonomia da vontade."]'::jsonb, 0, 'O princípio da precaução orienta a proteção diante de incerteza científica sobre riscos potencialmente graves, sem exigir certeza absoluta para agir.', 'medium', 'Princípios ambientais', 'multiple_choice', 'published', 5029, 'VUNESP', 'Geral')
